import React, {
    createContext,
    useContext,
    ReactNode,
    useState,
} from 'react'

type FeedType = {
    lineCards: number;
    id: string;
}

type StateContext = {
    feed: FeedType[];
    setFeed: (value: FeedType[]) => void;

    loading: boolean;
    setLoading: (value: boolean) => void;

    total: number;
    setTotal: (value: number) => void;

    page: number;
    setPage: (value: number) => void;

    buttonCardActive: boolean;
    setButtonCardActive: (value: boolean) => void;
}

type ProviderProps = {
    children: ReactNode;
}

export const Context = createContext({} as StateContext);

const Provider = ({ children }: ProviderProps) => {
    const [feed, setFeed] = useState<FeedType[]>([]);
    const [loading, setLoading] = useState(false);
    const [total, setTotal] = useState(101);
    const [page, setPage] = useState(1);
    const [buttonCardActive, setButtonCardActive] = useState(false);

    return (
        <Context.Provider value={{
            feed,
            setFeed,

            loading,
            setLoading,

            total,
            setTotal,

            page,
            setPage,

            buttonCardActive,
            setButtonCardActive,

        } as StateContext}>
            {children}
        </Context.Provider>
    );
};

function useContexState() {
    const context = useContext(Context);
    return context;
};

export {
    Provider,
    useContexState
};
